#!/usr/bin/env bash
# Build a Noctalia-tinted copy of Slot Beauty Dark Icons and select it.
#
# The original pack is never modified: a sibling theme is assembled from
# symlinks, and only the colourful folder icons under places/ are rewritten so
# the folder body lands exactly on Noctalia's `primary` colour.
# This section has been AI-generated by Gemini 3.8 Flash (High) on 21.11.2026
set -euo pipefail

CONFIG_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
DATA_HOME="${XDG_DATA_HOME:-$HOME/.local/share}"
CONFIG_HOME="${XDG_CONFIG_HOME:-$HOME/.config}"
SRC="${SLOT_BEAUTY_SRC:-}"
if [[ -z "$SRC" ]]; then
  for cand in \
    "$DATA_HOME/icons/Slot-Beauty-Dark-Icons-V-2" \
    "$HOME/.icons/Slot-Beauty-Dark-Icons-V-2" \
    "/usr/share/icons/Slot-Beauty-Dark-Icons-V-2" \
    "/usr/local/share/icons/Slot-Beauty-Dark-Icons-V-2"; do
    if [[ -d "$cand/places" ]]; then
      SRC="$cand"
      break
    fi
  done
  SRC="${SRC:-$DATA_HOME/icons/Slot-Beauty-Dark-Icons-V-2}"
fi
DEST="$DATA_HOME/icons/Slot-Beauty-Dark-Icons-V-2-Noctalia"
STATE="$CONFIG_HOME/noctalia/slot-beauty-icons.state"
COLOR_FILE="$CONFIG_DIR/colors-final"
THEME_NAME="Slot-Beauty-Dark-Icons-V-2-Noctalia"

# shellcheck source=pins.sh
source "$CONFIG_DIR/pins.sh"

# ---------------------------------------------------------------- target ----

TARGET=""
if [[ -f "$COLOR_FILE" ]]; then
  TARGET="$(head -n1 "$COLOR_FILE" | tr -d '[:space:]#')"
  TARGET="${TARGET:0:6}"
fi
if [[ ! "$TARGET" =~ ^[0-9a-fA-F]{6}$ ]]; then
  echo "Warning: colors-final holds no valid colour; leaving the icon theme as is" >&2
  exit 0
fi
TARGET="$(printf '%s' "$TARGET" | tr 'A-F' 'a-f')"

if [[ ! -d "$SRC/places" ]]; then
  echo "Warning: Slot Beauty Dark Icons not found at $SRC" >&2
  exit 0
fi
SRC="$(readlink -f "$SRC")"

# ------------------------------------------------------------ build theme ----

# Fast atomic theme synchronization:
# Never deletes active directories in-place to avoid falling back to Adwaita/Breeze.
STAMP="$DEST/.noctalia-color"
RECOLOR_SCRIPT="$CONFIG_DIR/recolor.py"
[[ -f "$RECOLOR_SCRIPT" ]] || RECOLOR_SCRIPT="$CONFIG_DIR/recolor4.py"

if [[ -f "$STAMP" && -d "$DEST/places" && "$(cat "$STAMP" 2>/dev/null)" == "$TARGET" ]]; then
  :
else
  python3 "$RECOLOR_SCRIPT" sync "$TARGET" "$SRC" "$DEST" --bodies "$CONFIG_DIR/bodies.tsv"
fi

# ----------------------------------------------------------- theme switch ----

ini_get() {
  [[ -f "$1" ]] || return 0
  sed -n -E "s|^[[:space:]]*$2[[:space:]]*=[[:space:]]*||p" "$1" | head -n1
}

ini_set() { # file group key value
  local file="$1" group="$2" key="$3" value="$4"
  mkdir -p "$(dirname "$file")"
  [[ -f "$file" ]] || printf '[%s]\n' "$group" > "$file"
  if grep -qE "^[[:space:]]*${key}[[:space:]]*=" "$file"; then
    if ! grep -qxF "${key}=${value}" "$file"; then
      sed -i -E "s|^[[:space:]]*${key}[[:space:]]*=.*|${key}=${value}|" "$file"
    fi
  elif grep -qxF "[${group}]" "$file"; then
    sed -i -E "0,/^\[${group}\]\$/s//[${group}]\n${key}=${value}/" "$file"
  else
    printf '\n[%s]\n%s=%s\n' "$group" "$key" "$value" >> "$file"
  fi
}

remember() { # key value
  mkdir -p "$(dirname "$STATE")"
  touch "$STATE"
  grep -qE "^$1=" "$STATE" || printf '%s=%s\n' "$1" "$2" >> "$STATE"
}

GTK3="$CONFIG_HOME/gtk-3.0/settings.ini"
GTK4="$CONFIG_HOME/gtk-4.0/settings.ini"
QT5="$CONFIG_HOME/qt5ct/qt5ct.conf"
QT6="$CONFIG_HOME/qt6ct/qt6ct.conf"

if command -v gsettings >/dev/null 2>&1; then
  current_gsettings="$(gsettings get org.gnome.desktop.interface icon-theme 2>/dev/null || true)"
  clean_gsettings="${current_gsettings//\'/}"
  if [[ -n "$clean_gsettings" && "$clean_gsettings" != "$THEME_NAME" ]]; then
    remember gsettings "$clean_gsettings"
    gsettings set org.gnome.desktop.interface icon-theme "'$THEME_NAME'" 2>/dev/null || true
  fi
fi

current_gtk3="$(ini_get "$GTK3" gtk-icon-theme-name)"
if [[ "$current_gtk3" != "$THEME_NAME" ]]; then
  [[ -n "$current_gtk3" ]] && remember gtk3 "$current_gtk3"
  ini_set "$GTK3" Settings gtk-icon-theme-name "$THEME_NAME"
fi

current_gtk4="$(ini_get "$GTK4" gtk-icon-theme-name)"
if [[ "$current_gtk4" != "$THEME_NAME" ]]; then
  [[ -n "$current_gtk4" ]] && remember gtk4 "$current_gtk4"
  ini_set "$GTK4" Settings gtk-icon-theme-name "$THEME_NAME"
fi

for conf in "$QT5" "$QT6"; do
  [[ -f "$conf" ]] || continue
  case "$conf" in
    "$QT5")
      current_qt="$(ini_get "$conf" icon_theme)"
      if [[ "$current_qt" != "$THEME_NAME" ]]; then
        [[ -n "$current_qt" ]] && remember qt5 "$current_qt"
        ini_set "$conf" Appearance icon_theme "$THEME_NAME"
      fi
      ;;
    "$QT6")
      current_qt="$(ini_get "$conf" icon_theme)"
      if [[ "$current_qt" != "$THEME_NAME" ]]; then
        [[ -n "$current_qt" ]] && remember qt6 "$current_qt"
        ini_set "$conf" Appearance icon_theme "$THEME_NAME"
      fi
      ;;
  esac
done

# ------------------------------------------------------------- theme pins ----

apply_pins() {
  local key file read_re write_re value
  while IFS='|' read -r key file read_re write_re; do
    [[ -n "$key" ]] || continue
    value="$(pin_value "$file" "$read_re")"
    [[ -n "$value" ]] || continue
    if [[ "$value" != "$THEME_NAME" ]]; then
      remember "$key" "$value"
      pin_write "$file" "$write_re" "$THEME_NAME"
    fi
  done < <(pin_rows)
}

apply_pins

exit 0
# End of AI-generated section.
